package cl.acis.catalogos.controller;
import cl.acis.catalogos.config.ActorHeaders; import cl.acis.catalogos.dto.*; import cl.acis.catalogos.model.TipoMotivo; import cl.acis.catalogos.service.CatalogoService; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") public class CatalogoController {final CatalogoService s;final ActorHeaders h;public CatalogoController(CatalogoService x,ActorHeaders a){s=x;h=a;}private ActorHeaders.Actor actor(HttpServletRequest q){return h.leer(q);}private void escritura(ActorHeaders.Actor a){h.exigir(a,"ADMINISTRADOR","JEFATURA");}
 @PostMapping("/clientes") ClienteResponse crearCliente(@Valid @RequestBody ClienteRequest r,HttpServletRequest q){ActorHeaders.Actor a=actor(q);escritura(a);return s.crearCliente(r);}@GetMapping("/clientes") List<ClienteResponse> clientes(HttpServletRequest q){actor(q);return s.clientes();}@GetMapping("/clientes/{id}") ClienteResponse cliente(@PathVariable Long id,HttpServletRequest q){actor(q);return s.cliente(id);}@PutMapping("/clientes/{id}") ClienteResponse editarCliente(@PathVariable Long id,@Valid @RequestBody ClienteRequest r,HttpServletRequest q){escritura(actor(q));return s.editarCliente(id,r);}@DeleteMapping("/clientes/{id}") ResponseEntity<Void> borrarCliente(@PathVariable Long id,HttpServletRequest q){escritura(actor(q));s.borrarCliente(id);return ResponseEntity.noContent().build();}
 @PostMapping("/equipos") EquipoResponse crearEquipo(@Valid @RequestBody EquipoRequest r,HttpServletRequest q){escritura(actor(q));return s.crearEquipo(r);}@GetMapping("/equipos") List<EquipoResponse> equipos(@RequestParam(required=false)Long clienteId,HttpServletRequest q){actor(q);return s.equipos(clienteId);}@GetMapping("/equipos/{id}") EquipoResponse equipo(@PathVariable Long id,HttpServletRequest q){actor(q);return s.equipo(id);}@PutMapping("/equipos/{id}") EquipoResponse editarEquipo(@PathVariable Long id,@Valid @RequestBody EquipoRequest r,HttpServletRequest q){escritura(actor(q));return s.editarEquipo(id,r);}@DeleteMapping("/equipos/{id}") ResponseEntity<Void> borrarEquipo(@PathVariable Long id,HttpServletRequest q){escritura(actor(q));s.borrarEquipo(id);return ResponseEntity.noContent().build();}
 @PostMapping("/motivos") MotivoResponse crearMotivo(@Valid @RequestBody MotivoRequest r,HttpServletRequest q){escritura(actor(q));return s.crearMotivo(r);}@GetMapping("/motivos") List<MotivoResponse> motivos(@RequestParam(required=false)TipoMotivo tipo,HttpServletRequest q){actor(q);return s.motivos(tipo);}@GetMapping("/motivos/{id}") MotivoResponse motivo(@PathVariable Long id,HttpServletRequest q){actor(q);return s.motivo(id);}@PutMapping("/motivos/{id}") MotivoResponse editarMotivo(@PathVariable Long id,@Valid @RequestBody MotivoRequest r,HttpServletRequest q){escritura(actor(q));return s.editarMotivo(id,r);}@DeleteMapping("/motivos/{id}") ResponseEntity<Void> borrarMotivo(@PathVariable Long id,HttpServletRequest q){escritura(actor(q));s.borrarMotivo(id);return ResponseEntity.noContent().build();}
}
